"use strict";
// An island class whose instances keep the listeners they are given.
class Channel {
  constructor(name) {
    this.name = name;
    this.listeners = [];
    this.payload = new Array(128).fill(0);
  }
  onMessage(fn) {
    this.listeners.push(fn);
  }
  deliver(text) {
    for (const fn of this.listeners) fn(text);
    return this.listeners.length;
  }
}

function churn(kib) {
  let total = 0;
  for (let i = 0; i < kib; i++) total += new Array(128).fill(i).length;
  return total;
}

// Channels island code keeps on its own.
const adopted = [];
function adopt(channel) {
  adopted.push(channel);
}
function broadcast(text) {
  let n = 0;
  for (const c of adopted) n += c.deliver(text);
  return n;
}

module.exports = { Channel, churn, adopt, broadcast };
